import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2020-02-20 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-02-20 :: Ceph Performance Meeting","date":"2020-02-20T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","Performance Optimization","Distributed Storage","IO Benchmark","Storage Cluster"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-02-20_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-02-20_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),t={name:"posts/2020/2020-02-20_-_-_Ceph_Performance_Meeting.md"};function o(n,e,s,h,u,d){return l(),i("div",null,[...e[0]||(e[0]=[r('<h3 id="改进后的会议纪要" tabindex="-1">改进后的会议纪要 <a class="header-anchor" href="#改进后的会议纪要" aria-label="Permalink to &quot;改进后的会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>日期：2020年2月20日</li><li>时间：上午</li></ul><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Josh</li><li>Mike</li><li>Igor</li><li>其他核心团队成员</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>PRC（Pull Request Community）更新</strong></p><ul><li>Igor提交了多个新的PR，包括使用延迟写入避免小块碎片化，以及基于AVL和位图的混合分配器。</li><li>讨论了其他PR的进展，如SPD cape性能改进、nvme设备代码优化、upper list和nvme设备分割等。</li></ul></li><li><p><strong>性能优化讨论</strong></p><ul><li>Igor分享了基于AVL和位图混合分配器的性能数据，讨论了内存使用和性能优化之间的权衡。</li><li>讨论了4k最小分配单元对性能的影响，特别是在读写操作中的表现。</li></ul></li><li><p><strong>IO 500基准测试</strong></p><ul><li>讨论了在Ceph上运行IO 500基准测试的进展和挑战，包括性能瓶颈和MDS（Metadata Server）的负载均衡问题。</li><li>提到了使用新的officinalis节点进行测试，以及尝试使用FUSE客户端时遇到的问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续优化和测试Igor的PR，特别是混合分配器和延迟写入策略。</li><li>继续进行IO 500基准测试，重点关注MDS的负载均衡和客户端性能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Igor将继续优化混合分配器和延迟写入策略，并分享更多性能数据。</li><li>继续进行IO 500基准测试，尝试解决性能瓶颈和MDS负载均衡问题。</li><li>使用Patrick的脚本进行更深入的性能分析和调试。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了Ceph在生产环境中的内存使用问题，以及如何通过优化分配器来解决。</li><li>提到了Ceph在IO 500基准测试中的排名，目标是提高性能并进入前13名。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在感谢所有参会人员的参与后结束，并约定下周再次开会。</li></ul><h3 id="分析与改进" tabindex="-1">分析与改进 <a class="header-anchor" href="#分析与改进" aria-label="Permalink to &quot;分析与改进&quot;">​</a></h3><ol><li><strong>准确性</strong>：改进后的总结准确反映了原始内容的要点，包括会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</li><li><strong>错误、误解或遗漏</strong>：原始总结中遗漏了关于Igor讨论的延迟写入和混合分配器的具体细节，以及关于IO 500基准测试中遇到的问题的深入讨论。</li><li><strong>改进点</strong>：改进后的总结增加了对Igor提出的优化策略的详细描述，以及IO 500基准测试中遇到的具体问题的讨论。</li></ol><p>通过这些改进，总结更加全面和准确，同时保留了会议中的关键技术和Ceph相关领域的英文关键词。</p>',18)])])}const p=a(t,[["render",o]]);export{_ as __pageData,p as default};
